    constraint CK_BIL_PAY_PAYMENT_AMOUNT check (AMT_PAYMENT > 0),
    constraint CK_BIL_PAY_PAYMENT_REVERSAL check ((SD_PAY_TYPE = 'PAYMENT' and ID_PAY_REVERSES is null)
