    constraint CK_BIL_STL_SETTLEMENT_AMOUNTS check (AMT_DISCOUNT >= 0 and AMT_INS >= 0 and AMT_PAT >= 0 and AMT_OTHER >= 0
        and ((SD_STL_TYPE <> 'REVERSAL' and AMT_GROSS >= 0 and AMT_NET >= 0)
