    AMT_OTHER_FUND decimal(24,6) not null,
    CD_CURRENCY varchar(3) not null,
    ID_CORRELATION varchar(128),
    ID_USER_CREATED bigint not null,
    DT_CREATED timestamp with time zone not null,
