    constraint CK_SUP_GOOD_RCPT_GR_STATUS check (SD_STATUS in ('RECEIVED', 'INSPECTING', 'ACCEPTED', 'PARTIALLY_ACCEPTED', 'REJECTED', 'POSTED', 'CANCELLED'))
);

create table RHN_SUP_GOOD_RCPT_LINE (
