create table if not exists RHN_BD_CLIN_SEM_VER (
    ID_CLIN_SEM_VER bigint not null,
    ID_TNT bigint not null,
    SD_CONCEPT_KIND varchar(32) not null,
    CD_CONCEPT varchar(96) not null,
    HASH_SEM_VER varchar(64) not null,
    SD_CHANGE_TYPE varchar(40) not null,
    DES_SOURCE varchar(256) not null,
    JSON_SNAPSHOT text not null,
    DT_RECORDED timestamp with time zone not null,
    CD_IDENTITY_KEY varchar(96),
    ID_USER_RECORDED bigint,
    constraint PK_BD_CLIN_SEM_VER primary key (ID_CLIN_SEM_VER),
    constraint UQ_BD_CLIN_SEM_IDENTITY unique (CD_IDENTITY_KEY)
);
create index if not exists IX_BD_CLIN_SEM_CONCEPT on RHN_BD_CLIN_SEM_VER (ID_TNT, SD_CONCEPT_KIND, CD_CONCEPT, ID_CLIN_SEM_VER);
comment on table RHN_BD_CLIN_SEM_VER is '临床语义版本；一行代表一次不可变概念版本或显示信息变更记录';
